head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF09314";
scwin.secugrpId = "";       // 증권그룹ID — init 에서 상장형 수익증권(PF) (원본 vSecugrpID)
scwin.savedState = "";      // 상세를 채운 직후의 값 — 수정 전 변경 여부 판정용 (원본 $c.data.isModified(dma_selectOne))
scwin.DISTR_MONTHS = 12;                    // 분배기준일 칸 수 (earngDistrBasMmdd1~12)

// 원본 : /pf/ULDSTF09314.gfm (상장원부 — 상장형 수익증권). gfm 은 저장소에 없고 W-Craft 1차 변환 + API 적용 개발 사본으로 분석했다.
/*
 * 화면 동작
 *  - 진입하면 명의개서대행기관·과세유형·복제유형 공통 코드를 받는다.
 *  - [종목 찾기](ULDSTF92017)로 PF 종목을 고르면 상장원부 상세와 LP회원 목록을 조회하고, 분배기준일 목록을 만든다(조회 버튼 없음).
 *  - 지정참가회사·거래상대방명01~10 만 고칠 수 있고, [수정]은 변경 확인 → 확인 → 업무처리번호 채번 → 수정 → 다시 조회.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF09314/ULDSTF09314.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09314.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 로딩 — 증권그룹 → 콤보 공통 코드 3종 → 빈 상세 상태 기억 → 달력 바인딩. 초기 조회는 없다(종목을 골라야 조회).
 * (원본 init — 숨겨 쓰던 유가증권 라벨·콤보와 txb_IDX_TOTAL_CD 는 마크업에서 지웠다, §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 증권그룹 — 원본 전역 vSecugrpID = SECUGRP_ID_PF
    scwin.secugrpId = $c.lc.getGlbValue("SECUGRP_ID_PF");

    // 2) 콤보 공통 코드 — 명의개서대행기관·과세유형·복제유형 (원본 fn_searchCode)
    await scwin.selectCodeList();

    // 3) 빈 상세 상태 — 조회 전 [수정]이 「변경 없음」으로 끝나도록
    scwin.savedState = scwin.getEditState();

    // 4) 달력 검사 바인딩(1회, 규칙 37) — 모두 조회 전용이지만 단일 달력 규약대로 건다(05923 선례)
    $c.date.checkCalendarFormat(cal_listDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(cal_isuDd, "yyyyMMdd");
    $c.date.checkCalendarFormat(cal_expDd, "yyyyMMdd");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_FindIsu_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(돋보기) 버튼 클릭 — 고르면 바로 조회한다. (원본 btn_searchIsu onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_FindIsu_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09314.btn_FindIsu_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 버튼 클릭. (원본 btn_update onclick — §4)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09314.btn_Update_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectCodeList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 콤보 공통 코드 3종을 한 번에 조회 → dlt_transstkAgntCd·dlt_taxTpCd·dlt_etfReplicaMethdTpCd. (원본 fn_searchCode — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectCodeList = async function () {
    dma_codReq.set("codeList", "TRANSSTK_AGNT_CD, TAX_TP_CD, ETF_REPLICA_METHD_TP_CD");
    const sbmOptions = {
        id : "sbm_selectCodeList",
        method : "get",
        action : "/api/listing/common/code/list-code-value",
        ref : "dma_codReq",
        target : "dlt_transstkAgntCd=body.TRANSSTK_AGNT_CD, dlt_taxTpCd=body.TAX_TP_CD, dlt_etfReplicaMethdTpCd=body.ETF_REPLICA_METHD_TP_CD",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장원부 상세 조회 → dma_detail. (원본 fn_read_sync 첫 조회 — 개발 사본은 상세 dataMap 전체를 요청 ref 로 보냈다, §5.2)
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectDetail = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/pf/listed-register/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return false;      // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result?.responseJSON?.success === true;
};

/**
 * @method
 * @name scwin.selectLpList
 * @author Inswave
 * @date 2026. 10. 30
 * @description LP회원 목록 조회 → dlt_lpmbrno. (원본 fn_read_sync 둘째 조회 — §5.3)
 * @param {String} isuCd 종목코드
 * @returns
 * @hidden N
 */
scwin.selectLpList = async function (isuCd) {
    const sbmOptions = {
        id : "sbm_selectLpList",
        method : "get",
        action : "/api/listing/lstproc/pf/listed-register/select-list-lpmbrno",
        target : "dlt_lpmbrno=body",
        gridview : "grd_LP",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
};

/**
 * @method
 * @name scwin.modifyTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상장원부 수정 전송 — 상세를 그대로 보낸다. 성공하면 안내하고 다시 조회한다. (원본 fn_trs — §5.4)
 * @returns
 * @hidden N
 */
scwin.modifyTrs = async function () {
    const sbmOptions = {
        id : "sbm_modifyTrs",
        method : "post",
        action : "/api/listing/lstproc/pf/listed-register/modify",
        ref : "dma_detail",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀
    // TODO: modify 응답 정의가 화면에 없다 — 통신 성공(success)만으로 판정한다 (§10 #3)
    if (result?.responseJSON?.success !== true) return;

    await $c.win.alert($c.data.getMessage("com_complete_0150", "수정"));
    await scwin.search();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목 찾기(ULDSTF92017) — 고른 종목으로 조회한다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 btn_searchIsu onclick 의 $c.cm.jongmokSearch — 반환 계약이 없는 Gauce 잔재라 pcc popFindIsu 로, §6.1)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const result = await $c.lc.popFindIsu(scwin.secugrpId);
    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정(개발 사본은 판정 없이 값을 넣었다)
    if (result?.isCloseButtonClick === true || $c.util.isEmpty(result?.isuCd)) return;

    dma_search.set("isuCd", result.isuCd);
    dma_search.set("isuNm", result.isuKorNm ?? "");

    await scwin.search();
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 30
 * @description 조회 — 이전 종목 값이 남지 않게 비우고 상세 → 분배기준일 목록 → 변경 판정 기준 → LP회원 순서로 채운다. (원본 fn_read_sync — §6.2)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    const isuCd = dma_search.get("isuCd");

    dma_detail.setEmptyValue();
    dlt_distrBasMmdd.removeAll();
    dlt_lpmbrno.removeAll();

    if (await scwin.selectDetail(isuCd)) {
        scwin.setDistrBasMmdd();
    }
    scwin.savedState = scwin.getEditState();

    await scwin.selectLpList(isuCd);
};

/**
 * @method
 * @name scwin.setDistrBasMmdd
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상세의 분배기준일01~12 중 값이 있는 것만 모아 분배기준일 목록에 넣는다.
 * (원본 fn_getDistrBasMmDd — 행을 하나씩 더하면서 (i-1) 번째 행에 써 빈 달이 끼면 엉뚱한 행에 쓰던 결함을 고침, §8 #3)
 * @returns
 * @hidden N
 */
scwin.setDistrBasMmdd = function () {
    const rows = [];
    for (let i = 1; i <= scwin.DISTR_MONTHS; i++) {
        const mmdd = String(dma_detail.get("earngDistrBasMmdd" + i) ?? "");
        if (mmdd !== "") rows.push({ earngDistrBasMmdd : mmdd });
    }
    dlt_distrBasMmdd.setJSON(rows);
};

/**
 * @method
 * @name scwin.getEditState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상세 입력값의 현재 상태 문자열 — 조회 직후 값과 비교해 바뀌었는지 본다. (원본 $c.data.isModified(dma_selectOne) — §6.3)
 * @returns {String} 상세 입력값 JSON 문자열
 * @hidden N
 */
scwin.getEditState = function () {
    return JSON.stringify(dma_detail.getJSON());
};

/**
 * @method
 * @name scwin.getBzProcsNoOf
 * @author Inswave
 * @date 2026. 10. 30
 * @description 채번 응답에서 업무처리번호를 꺼낸다 — 문자열이면 그대로, 객체면 bzProcsNo. (pcc getNewBzProcNo 는 응답 JSON 을 그대로 돌려준다)
 * @param {*} body 채번 응답 body
 * @returns {String} 업무처리번호 (없으면 빈 문자열)
 * @hidden N
 */
scwin.getBzProcsNoOf = function (body) {
    if (body === null || body === undefined) return "";
    if (typeof body === "object") return String(body.bzProcsNo ?? "");
    return String(body);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정 — 종목·변경 여부 확인 → 확인 → 업무처리번호 채번(14자리) → 수정. (원본 fn_update — §6.4)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    if ($c.util.isEmpty(dma_search.get("isuCd"))) {
        await $c.win.alert($c.data.getMessage("com_req_select", "종목"));
        return;
    }
    // com_crud_0202 — 변경된 내용 없음 (원본 isModified)
    if (scwin.getEditState() === scwin.savedState) {
        await $c.win.alert($c.data.getMessage("com_crud_0202"));
        return;
    }
    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess("U")) return;

    // TODO: pcc 채번은 주식 변경상장 경로(stock/chglisting/new-bzprocsno)다 — PF 상장원부 수정도 같은 채번인지 확인 (§10 #2)
    const res = await $c.stf.getNewBzProcNo();
    const bzProcsNo = scwin.getBzProcsNoOf(res?.body ?? res);
    if (bzProcsNo.length !== 14) {
        await $c.win.alert($c.data.getMessage("com_complete_0151", "업무처리번호생성"));
        return;
    }

    dma_detail.set("bzProcsNo", bzProcsNo);
    await scwin.modifyTrs();
};
